  // 跨队事件必须明确写成赛前、比赛中或赛后互动。现有通用模板大多描述本队
  // 更衣室、训练和旅行，不能仅因旧 registry 标了 cross-team 就把对手塞进模板。
  const CROSS_TEAM_GENERIC_FAMILIES = new Set(["public-handshake", "rivalry-banter"]);

  // 先选事件类别，再在类别内部选具体事件。否则候选数量本身会变成概率：
  // 三条真实伤病会被数百条通用排列淹没，人物专属事件也很难出现。
  const EVENT_CLASS_WEIGHTS = Object.freeze({
    injury: 4.4,
    named: 2.4,
    crossTeam: 1,
    personality: 1.2,
    generic: 1.4
  });

  // 由候选构建器注入。运行时只认稳定英文球员身份，不按中文显示名或数组下标碰运气。
  let PERSONAL_ON_COURT_LIBRARY = Object.freeze({ schemaVersion: "unconfigured", packs: Object.freeze({}) });

  const text = value => String(value == null ? "" : value).trim();
  const unique = values => [...new Set((values || []).filter(Boolean))];
  const clamp = (value, low, high) => Math.max(low, Math.min(high, Number(value) || 0));
  const hash32 = value => {
    let hash = 2166136261;
    for (const char of text(value)) {
      hash ^= char.charCodeAt(0);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  };
  const createRng = seed => {
    let state = hash32(seed) || 0x9e3779b9;
    return () => {
      state += 0x6D2B79F5;
      let cursor = state;
      cursor = Math.imul(cursor ^ cursor >>> 15, cursor | 1);
      cursor ^= cursor + Math.imul(cursor ^ cursor >>> 7, cursor | 61);
      return ((cursor ^ cursor >>> 14) >>> 0) / 4294967296;
    };
  };
  const pick = (items, rng) => items?.length ? items[Math.floor(rng() * items.length) % items.length] : null;
  const weightedPick = (items, weight, rng) => {
    if (!items?.length) return null;
    const rows = items.map(item => ({ item, weight: Math.max(.001, Number(weight(item)) || 0) }));
    const total = rows.reduce((sum, row) => sum + row.weight, 0);
    let cursor = rng() * total;
    for (const row of rows) {
      cursor -= row.weight;
      if (cursor <= 0) return row.item;
    }
    return rows.at(-1).item;
  };

  function configureOnCourtCallLibrary(library) {
    if (!library || Number(library.playerCount) !== 79 || Number(library.callCount) !== 394) {
      throw new Error("invalid-on-court-call-library-counts");
    }
    const packs = library.packs || {};
    if (Object.keys(packs).length !== 79) throw new Error("invalid-on-court-player-pack-count");
    PERSONAL_ON_COURT_LIBRARY = Object.freeze({ ...library, packs: Object.freeze(packs) });
    return { schemaVersion: library.schemaVersion, playerCount: 79, callCount: 394 };
  }

  function canonical(value, aliases) {
    const clean = text(value);
    return aliases?.[clean] || clean;
  }

  function cardName(card) {
    return text(card?.displayName || card?.name || card?.raw?.displayName || card?.raw?.name);
  }

  function cardSubject(card, aliases) {
    return canonical(text(card?.name || card?.raw?.name || card?.displayName), aliases);
  }

  function cardKey(card) {
    return text(card?.cardKey || card?.v35?.sourceKey || card?.sourceKey || card?.id || `${cardName(card)}|${card?.version || ""}`);
  }

  function normalizeTeam(team, aliases) {
    return {
      id: text(team?.id || team?.teamId),
      isPlayer: team?.isPlayer === true || text(team?.id || team?.teamId) === "player-team",
      conference: text(team?.conference),
      lineup: (team?.lineup || team?.cards || []).map(card => ({
        raw: card,
        key: cardKey(card),
        name: cardName(card),
        subject: cardSubject(card, aliases),
        version: text(card?.version || card?.displayVersion),
        sourceType: text(card?.sourceType || card?.poolType || "unknown")
      })).filter(card => card.subject)
    };
  }

  function normalizeGame(game, index) {
    return {
      raw: game,
      round: Number(game?.round || game?.gameNumber || game?.number || index + 1),
      homeTeamId: text(game?.homeTeamId || game?.teamAId || game?.home?.teamId),
      awayTeamId: text(game?.awayTeamId || game?.teamBId || game?.away?.teamId),
      winnerId: text(game?.winnerId)
    };
  }

  function buildLeagueContext(result, playerCards, registry) {
    const ledger = result?.unifiedLeagueLedger || {};
    const teams = (ledger.teams || []).map(team => normalizeTeam(team, registry.aliases));
    let playerTeam = teams.find(team => team.isPlayer);
    if (!playerTeam) {
      playerTeam = { id: "player-team", isPlayer: true, conference: "", lineup: (playerCards || []).map(card => ({
        raw: card,
        key: cardKey(card),
        name: cardName(card),
        subject: cardSubject(card, registry.aliases),
        version: text(card?.version || card?.displayVersion),
        sourceType: "public"
      })) };
      teams.unshift(playerTeam);
    }
    const opponentTeams = teams.filter(team => !team.isPlayer);
    const teamById = new Map(teams.map(team => [team.id, team]));
    const rawGames = ledger.regularSeason?.games || ledger.schedule || [];
    const games = rawGames.map(normalizeGame).filter(game => game.homeTeamId === playerTeam.id || game.awayTeamId === playerTeam.id);
    const fallbackGames = games.length ? games : Array.from({ length: 82 }, (_, index) => {
      const opponent = opponentTeams[index % Math.max(1, opponentTeams.length)];
      return { round: index + 1, homeTeamId: index % 2 ? playerTeam.id : opponent?.id, awayTeamId: index % 2 ? opponent?.id : playerTeam.id, winnerId: "" };
    });
    const sourceTypes = unique(opponentTeams.flatMap(team => team.lineup.map(card => card.sourceType)));
    return { ledger, teams, playerTeam, opponentTeams, teamById, games: fallbackGames, sourceTypes };
  }

  function opponentForGame(game, context) {
    const id = game.homeTeamId === context.playerTeam.id ? game.awayTeamId : game.homeTeamId;
    return context.teamById.get(id) || null;
  }

  function stageContext(stage, league) {
    const games = league.games.filter(game => game.round >= stage.start && game.round <= stage.end);
    const opponents = unique(games.map(game => opponentForGame(game, league)).filter(Boolean));
    return { ...stage, games, opponents, opponentCards: opponents.flatMap(team => team.lineup) };
  }

  function profileMap(registry) {
    return new Map((registry.profiles || []).map(profile => [canonical(profile.subject, registry.aliases), profile]));
  }

  function eligibleFamilies(card, profiles, familyById, registry) {
    const profile = profiles.get(card.subject);
    if (!profile) return [];
    const ids = new Set(profile.runtimeGenericFamilyIds || profile.eligibleGenericFamilyIds || []);
    for (const family of familyById.values()) {
      if ((family.traits || []).some(trait => (profile.canonicalTraits || []).includes(trait))) ids.add(family.id);
    }
    return [...ids].map(id => familyById.get(id)).filter(Boolean);
  }

  function participantSignature(cards) {
    return unique(cards.map(card => card.subject)).sort().join("+");
  }

  function semanticSignature(candidate) {
    return [candidate.kind, candidate.familyId, participantSignature(candidate.participants), candidate.stageId].join("|");
  }

  function makeGenericCandidates(node, league, profiles, registry) {
    const familyById = new Map((registry.genericFamilies || []).map(family => [family.id, family]));
    const own = league.playerTeam.lineup;
    const candidates = [];
    for (const actor of own) {
      for (const family of eligibleFamilies(actor, profiles, familyById, registry)) {
        if ((family.stages || []).length && !family.stages.includes("regular") && !family.stages.includes(node.id)) continue;
        const policy = family.participantPolicy || {};
        const teammatePool = own.filter(card => card.key !== actor.key);
        const opponentPool = node.opponentCards || [];
        if (policy.allowSingle !== false) candidates.push({
          id: `generic-single-${node.id}-${family.id}-${actor.key}`,
          kind: "generic-single",
          familyId: family.id,
          family,
          participants: [actor],
          opponents: [],
          stageId: node.id,
          weight: 1
        });
        if (policy.allowPair && teammatePool.length) {
          for (const teammate of teammatePool.slice(0, 4)) candidates.push({
            id: `generic-pair-${node.id}-${family.id}-${actor.key}-${teammate.key}`,
            kind: "generic-pair",
            familyId: family.id,
            family,
            participants: [actor, teammate],
            opponents: [],
            stageId: node.id,
            weight: .88
          });
        }
        if (policy.allowGroup && teammatePool.length >= 2) candidates.push({
          id: `generic-group-${node.id}-${family.id}-${actor.key}`,
          kind: policy.scopes?.includes("whole-team") ? "whole-team" : "generic-group",
          familyId: family.id,
          family,
          participants: [actor, ...teammatePool.slice(0, 3)],
          opponents: [],
          stageId: node.id,
          weight: .76
        });
        if (policy.scopes?.includes("cross-team") && CROSS_TEAM_GENERIC_FAMILIES.has(family.id) && opponentPool.length) {
          for (const opponent of opponentPool.slice(0, 12)) candidates.push({
            id: `generic-cross-${node.id}-${family.id}-${actor.key}-${opponent.key}`,
            kind: "cross-team",
            familyId: family.id,
            family,
            participants: [actor],
            opponents: [opponent],
            stageId: node.id,
            weight: 1.08
          });
        }
      }
    }
    // 所有真实赛程都保留低权重的跨队公开互动入口，但只使用专门的安全文案，
    // 不借用任何本队训练/更衣室模板。
    if (!candidates.some(candidate => candidate.kind === "cross-team")) {
      const family = familyById.get("public-handshake");
      if (family) for (const actor of own) {
        for (const opponent of (node.opponentCards || []).slice(0, 4)) candidates.push({
          id: `generic-cross-safe-${node.id}-${actor.key}-${opponent.key}`,
          kind: "cross-team",
          familyId: family.id,
          family,
          participants: [actor],
          opponents: [opponent],
          stageId: node.id,
          weight: .54
        });
      }
    }
    return candidates;
  }

  function makePersonalityCollisionCandidates(node, league, profiles, registry) {
    const familyById = new Map((registry.genericFamilies || []).map(family => [family.id, family]));
    const familyIdsFor = card => eligibleFamilies(card, profiles, familyById, registry).map(family => family.id);
    const own = league.playerTeam.lineup;
    const candidates = [];
    for (let leftIndex = 0; leftIndex < own.length; leftIndex += 1) {
      for (let rightIndex = leftIndex + 1; rightIndex < own.length; rightIndex += 1) {
        const left = own[leftIndex];
        const right = own[rightIndex];
        const leftTraits = profiles.get(left.subject)?.canonicalTraits || [];
        const rightTraits = profiles.get(right.subject)?.canonicalTraits || [];
        const trainingNightlifePair = leftTraits.includes("trainingDriven") && rightTraits.includes("nightlifeVisible")
          ? [left, right]
          : rightTraits.includes("trainingDriven") && leftTraits.includes("nightlifeVisible") ? [right, left] : null;
        if (trainingNightlifePair) {
          // 这是“训练狂 × 夜生活型”的通用人格碰撞，不再要求 Kobe 与 Harden 同时出现。
          // 任何具备对应证据标签的两名球员都能触发，原先未核实的专属组合事件由构建器移除。
          candidates.push({
            id: `personality-pair-${node.id}-training-nightlife-${trainingNightlifePair.map(card => card.key).join("-")}`,
            kind: "personality-pair-collision",
            familyId: "training-nightlife-crossing",
            event: {
              titleOptions: ["凌晨四点，两条完全不同的作息撞在一起"],
              detailOptions: ["天还没亮，{{p0}}已经完成第一组训练，{{p1}}刚结束夜间行程回到酒店。两人在大堂打了个照面，谁也没解释为什么会在这个时间出现；第二天训练照常，这次偶遇只留下一个被全队反复讲的梗。"],
              displayLabel: "人物性格碰撞"
            },
            participants: trainingNightlifePair,
            opponents: [],
            stageId: node.id,
            collisionBasis: "training-driven-x-nightlife-visible",
            weight: 1.5
          });
        }
        const leftIds = familyIdsFor(left);
        const rightIds = familyIdsFor(right);
        const shared = leftIds.filter(id => rightIds.includes(id));
        const union = unique([...shared, ...leftIds, ...rightIds]);
        for (const id of union.slice(0, shared.length ? 3 : 2)) {
          const family = familyById.get(id);
          if (!family) continue;
          candidates.push({
            id: `personality-pair-${node.id}-${id}-${left.key}-${right.key}`,
            kind: "personality-pair-collision",
            familyId: id,
            family,
            participants: [left, right],
            opponents: [],
            stageId: node.id,
            collisionBasis: shared.includes(id) ? "shared-eligibility" : "contrasting-eligibility",
            weight: shared.includes(id) ? 1.24 : .92
          });
        }
      }
    }
    for (const family of familyById.values()) {
      const members = own.filter(card => familyIdsFor(card).includes(family.id));
      if (members.length < 2) continue;
      candidates.push({
        id: `personality-group-${node.id}-${family.id}`,
        kind: members.length >= 4 ? "whole-team-personality" : "personality-group-collision",
        familyId: family.id,
        family,
        participants: members.slice(0, 5),
        opponents: [],
        stageId: node.id,
        collisionBasis: "multi-profile-shared-eligibility",
        weight: 1.12
      });
    }
    for (const actor of own) {
      const actorIds = familyIdsFor(actor);
      for (const opponent of (node.opponentCards || []).slice(0, 40)) {
        const opponentIds = familyIdsFor(opponent);
        const shared = actorIds.filter(id => opponentIds.includes(id));
        const id = shared.find(candidateId => CROSS_TEAM_GENERIC_FAMILIES.has(candidateId))
          || actorIds.find(candidateId => CROSS_TEAM_GENERIC_FAMILIES.has(candidateId));
        const family = familyById.get(id);
        if (!family) continue;
        candidates.push({
          id: `personality-cross-${node.id}-${id}-${actor.key}-${opponent.key}`,
          kind: "cross-team-personality-collision",
          familyId: id,
          family,
          participants: [actor],
          opponents: [opponent],
          stageId: node.id,
          collisionBasis: shared.length ? "shared-eligibility" : "contrasting-eligibility",
          weight: shared.length ? 1.3 : 1.04
        });
      }
    }
    if (!candidates.some(candidate => candidate.kind === "cross-team-personality-collision")) {
      const family = familyById.get("rivalry-banter");
      if (family) for (const actor of own) {
        const actorIds = familyIdsFor(actor);
        for (const opponent of (node.opponentCards || []).slice(0, 4)) {
          const shared = actorIds.filter(id => familyIdsFor(opponent).includes(id));
          if (!shared.length) continue;
          candidates.push({
            id: `personality-cross-safe-${node.id}-${actor.key}-${opponent.key}`,
            kind: "cross-team-personality-collision",
            familyId: family.id,
            family,
            participants: [actor],
            opponents: [opponent],
            stageId: node.id,
            collisionBasis: `shared-${shared[0]}`,
            weight: .58
          });
        }
      }
    }
    return candidates;
  }

  function versionMatches(event, card) {
    const keys = event.applicableVersionKeys || [];
    if (!keys.length) return true;
    return keys.includes(card.key) || keys.some(key => card.key.includes(key) || `${card.subject}|${card.version}`.includes(key));
  }

  function makeSpecialCandidates(node, league, registry, includeRumor) {
    const ownBySubject = new Map(league.playerTeam.lineup.map(card => [card.subject, card]));
    const opponentBySubject = new Map((node.opponentCards || []).map(card => [card.subject, card]));
    const allBySubject = new Map([...ownBySubject, ...opponentBySubject]);
    const rows = includeRumor ? [...(registry.specialEvents || []), ...(registry.rumorEvents || [])] : registry.specialEvents || [];
    const candidates = [];
    for (const event of rows) {
      if (event.stage === "playoffs") continue;
      const subjects = unique((event.subjects || [event.anchorSubject, ...(event.relatedSubjects || [])]).map(value => canonical(value, registry.aliases)));
      const cards = subjects.map(subject => allBySubject.get(subject)).filter(Boolean);
      if (!cards.length || !cards.some(card => ownBySubject.has(card.subject))) continue;
      const minimum = Number(event.minimumSubjects || 1);
      if (cards.length < minimum) continue;
      // 关系事件必须让 registry 明确列出的所有人物都真实出现在本队或当前阶段对手中。
      // 单人历史新闻里的背景人物（例如 Booker 记录中的 Tyler Ulis）不能被当成本季参与者。
      if (event.relationship && (subjects.length < 2 || cards.length !== subjects.length)) continue;
      if ((event.applicableVersionKeys || []).length && !cards.some(card => versionMatches(event, card))) continue;
      candidates.push({
        id: `${event.id}-${node.id}`,
        kind: event.relationship || minimum > 1 ? "named-relationship" : "named-special",
        familyId: event.eventFamily || event.id,
        event,
        participants: cards.filter(card => ownBySubject.has(card.subject)),
        opponents: cards.filter(card => opponentBySubject.has(card.subject)),
        stageId: node.id,
        weight: event.relationship ? 1.62 : 1.36
      });
    }
    return candidates;
  }

  function relationshipGroupKey(event, registry) {
    return text(event.groupKey || event.sharedRelationshipGroupKey)
      || unique((event.subjects || []).map(value => canonical(value, registry.aliases))).sort().join(" + ");
  }

  function relationshipRows(registry) {
    const overlay = registry.relationshipOverlay?.events;
    return Array.isArray(overlay) && overlay.length
      ? overlay
      : [...(registry.specialEvents || []), ...(registry.rumorEvents || [])];
  }

  function relationshipCardKeys(card) {
    return unique([
      card?.key,
      card?.raw?.cardKey,
      card?.raw?.sourceKey,
      card?.raw?.stableKey,
      card?.raw?.id
    ].map(text));
  }

  function relationshipVersionTokenMatches(card, tokens) {
    if (!Array.isArray(tokens) || !tokens.length) return true;
    const haystacks = unique([
      ...relationshipCardKeys(card),
      card?.version,
      card?.raw?.version,
      card?.raw?.displayVersion,
      card?.raw?.subtitle
    ].map(value => text(value).toLowerCase()));
    return tokens.some(token => haystacks.some(value => value.includes(text(token).toLowerCase())));
  }

  function matchLineupRelationship(event, lineup, registry) {
    const bySubject = new Map();
    for (const card of lineup || []) {
      if (!bySubject.has(card.subject)) bySubject.set(card.subject, []);
      bySubject.get(card.subject).push(card);
    }
    const required = unique((event.requiredSubjects?.length ? event.requiredSubjects : event.subjects || [])
      .map(value => canonical(value, registry.aliases)));
    const optional = unique((event.optionalSubjects || []).map(value => canonical(value, registry.aliases)))
      .filter(subject => !required.includes(subject));
    const conditionFor = subject => (event.versionConditions || [])
      .find(condition => canonical(condition.subject, registry.aliases) === subject);
    const selected = [];
    for (const subject of required) {
      const card = [...(bySubject.get(subject) || [])]
        .sort((left, right) => left.key.localeCompare(right.key))
        .find(candidate => relationshipVersionTokenMatches(candidate, conditionFor(subject)?.versionIncludes || []));
      if (!card) return null;
      selected.push(card);
    }
    for (const subject of optional) {
      const card = [...(bySubject.get(subject) || [])]
        .sort((left, right) => left.key.localeCompare(right.key))
        .find(candidate => relationshipVersionTokenMatches(candidate, conditionFor(subject)?.versionIncludes || []));
      if (card) selected.push(card);
    }
    const cards = [...new Map(selected.map(card => [card.key, card])).values()];
    if (cards.length < Number(event.minimumSubjects || required.length)) return null;

    const applicableBySubject = new Map();
    for (const key of event.applicableVersionKeys || []) {
      const subject = canonical(text(key).split("|")[0], registry.aliases);
      if (!applicableBySubject.has(subject)) applicableBySubject.set(subject, []);
      applicableBySubject.get(subject).push(text(key));
    }
    for (const [subject, keys] of applicableBySubject) {
      const subjectCards = cards.filter(card => card.subject === subject);
      if (subjectCards.length && !subjectCards.some(card => relationshipCardKeys(card).some(key => keys.includes(key)))) return null;
    }
    return cards;
  }

  function lineupRelationshipGroups(lineup, registry, sourceTeamId, scope) {
    const rows = relationshipRows(registry);
    const groups = new Map();
    for (const event of rows) {
      if (event.relationship !== true || event.stage === "playoffs") continue;
      const cards = matchLineupRelationship(event, lineup, registry);
      if (!cards || cards.length < 2) continue;
      const groupKey = relationshipGroupKey(event, registry);
      if (!groups.has(groupKey)) groups.set(groupKey, []);
      groups.get(groupKey).push({ event, cards, groupKey, sourceTeamId, scope });
    }
    return groups;
  }

  function realizePlannedRelationship(selection, node, registry, seed) {
    const candidate = {
      id: `${selection.event.id}-${node.id}`,
      kind: "named-relationship",
      familyId: selection.event.eventFamily || selection.event.id,
      event: selection.event,
      participants: selection.cards,
      opponents: [],
      stageId: node.id,
      weight: 1
    };
    const event = realize(candidate, registry, createRng(seed));
    event.eventClass = "named";
    event.relationshipScope = selection.scope;
    event.relationshipGroupKey = selection.groupKey;
    event.sourceTeamId = selection.sourceTeamId;
    if (selection.scope === "hidden-opponent-lineup") {
      const opponentNames = event.participants.map(player => player.name).filter(Boolean);
      event.opponents = event.participants;
      event.participants = [];
      event.title = `对手阵中的${event.title}`;
      event.detail = `${node.label}的一场比赛前，对手阵中的${opponentNames.join("和")}成为焦点：${event.detail}`;
    }
    return event;
  }

  function resolveSeasonRelationships({ nodes, league, registry, baseSeed }) {
    const playerGate = clamp(registry.probability?.playerLineupRelationshipGate ?? .8, 0, 1);
    const hiddenGate = clamp(registry.probability?.hiddenOpponentLineupRelationshipGate ?? .4, 0, 1);
    const playerMaximum = Math.max(1, Number(registry.probability?.playerLineupRelationshipMaximum) || 3);
    const ownGroups = lineupRelationshipGroups(league.playerTeam.lineup, registry, league.playerTeam.id, "player-lineup");
    const ownSelected = [...ownGroups.entries()].flatMap(([groupKey, variants]) => {
      const gateSeed = `${baseSeed}|nba82-player-relationship-gate-v1|${groupKey}`;
      if (createRng(gateSeed)() >= playerGate) return [];
      const sorted = [...variants].sort((left, right) => left.event.id.localeCompare(right.event.id));
      return [{
        ...pick(sorted, createRng(`${gateSeed}|variant`)),
        order: createRng(`${gateSeed}|order`)()
      }];
    }).sort((left, right) => left.order - right.order || left.groupKey.localeCompare(right.groupKey))
      .slice(0, playerMaximum);

    const hiddenOptions = [];
    for (const team of league.opponentTeams) {
      const eligibleNodes = nodes.filter(node => node.opponents.some(opponent => opponent.id === team.id));
      if (!eligibleNodes.length) continue;
      for (const [groupKey, variants] of lineupRelationshipGroups(team.lineup, registry, team.id, "hidden-opponent-lineup")) {
        const sorted = [...variants].sort((left, right) => left.event.id.localeCompare(right.event.id));
        hiddenOptions.push({
          ...pick(sorted, createRng(`${baseSeed}|nba82-hidden-relationship-variant-v1|${team.id}|${groupKey}`)),
          eligibleNodes,
          order: createRng(`${baseSeed}|nba82-hidden-relationship-order-v1|${team.id}|${groupKey}`)()
        });
      }
    }
    const hiddenSelected = hiddenOptions.length
      && createRng(`${baseSeed}|nba82-hidden-relationship-season-gate-v1`)() < hiddenGate
      ? [[...hiddenOptions].sort((left, right) => left.order - right.order || left.groupKey.localeCompare(right.groupKey))[0]]
      : [];

    const nodeOrder = nodes.map(node => ({ node, order: createRng(`${baseSeed}|nba82-relationship-node-order-v1|${node.id}`)() }))
      .sort((left, right) => left.order - right.order || left.node.id.localeCompare(right.node.id)).map(row => row.node);
    const byNode = new Map(nodes.map(node => [node.id, []]));
    const occupiedNodeIds = new Set();
    ownSelected.forEach((selection, index) => {
      const node = nodeOrder[index % nodeOrder.length];
      occupiedNodeIds.add(node.id);
      byNode.get(node.id).push(realizePlannedRelationship(
        selection, node, registry, `${baseSeed}|nba82-player-relationship-copy-v1|${selection.groupKey}|${node.id}`
      ));
    });
    for (const selection of hiddenSelected) {
      const node = selection.eligibleNodes.find(candidate => !occupiedNodeIds.has(candidate.id)) || selection.eligibleNodes[0];
      occupiedNodeIds.add(node.id);
      byNode.get(node.id).push(realizePlannedRelationship(
        selection, node, registry, `${baseSeed}|nba82-hidden-relationship-copy-v1|${selection.sourceTeamId}|${selection.groupKey}|${node.id}`
      ));
    }
    return {
      byNode,
      trace: {
        playerGate,
        hiddenOpponentSeasonGate: hiddenGate,
        playerEligibleGroups: ownGroups.size,
        playerSelectedGroups: ownSelected.map(selection => selection.groupKey),
        hiddenOpponentEligibleGroups: hiddenOptions.length,
        hiddenOpponentSelectedGroups: hiddenSelected.map(selection => `${selection.sourceTeamId}|${selection.groupKey}`)
      }
    };
  }

  function makeInjuryCandidates(node, result, league, registry) {
    const availability = result?.availabilityLedger || [];
    const cardByKey = new Map(league.playerTeam.lineup.map(card => [card.key, card]));
    const candidates = [];
    for (const row of availability) {
      const missed = Number(row.missedGames || Math.max(0, 82 - Number(row.gp || 82)));
      if (missed <= 0) continue;
      const blueprint = (registry.injuryBlueprints || []).find(item => missed >= item.minMissed && missed <= item.maxMissed) || registry.injuryBlueprints?.at(-1);
      const card = cardByKey.get(text(row.cardKey)) || league.playerTeam.lineup.find(item => String(item.raw?.id) === String(row.cardId));
      if (!blueprint || !card) continue;
      const preferredStage = missed <= 5 ? "stretch-run" : missed <= 16 ? "all-star-window" : "first-half";
      if (node.id !== preferredStage) continue;
      candidates.push({
        id: `injury-${node.id}-${card.key}`,
        kind: "injury",
        familyId: blueprint.id,
        blueprint,
        missedGames: missed,
        participants: [card],
        opponents: [],
        stageId: node.id,
        weight: 1.18
      });
    }
    return candidates;
  }

  function fillCopy(value, participants = [], opponents = [], variables = {}) {
    let output = text(value);
    const participantNames = participants.map(card => card.name || card.subject);
    const opponentNames = opponents.map(card => card.name || card.subject);
    for (const [key, replacement] of Object.entries(variables || {})) {
      output = output.replaceAll(`{{${key}}}`, text(replacement));
    }
    participantNames.forEach((name, index) => { output = output.replaceAll(`{{p${index}}}`, name); });
    opponentNames.forEach((name, index) => { output = output.replaceAll(`{{o${index}}}`, name); });
    output = output.replaceAll("{{p0}}", participantNames[0] || "一名球员");
    output = output.replaceAll("{{o0}}", opponentNames[0] || "一名对手");
    if (participantNames[1]) {
      // 只有两个已知参与者时，不能把“几名/两名队友”硬替换成一个人名；复数保持自然称呼。
      output = output.replaceAll("一名队友", participantNames[1]);
    }
    if (opponentNames[0]) output = output.replace(/昔日对手|对手/g, match => match === "昔日对手" ? `昔日对手${opponentNames[0]}` : opponentNames[0]);
    // 资源字段即使缺失也不能把 {{hook}} 一类内部占位符泄漏到玩家界面。
    output = output.replace(/\{\{[a-zA-Z0-9_-]+\}\}/g, "这段公开记录");
    return output;
  }

  function crossTeamCopy(candidate) {
    const actor = candidate.participants[0]?.name || candidate.participants[0]?.subject || "一名球员";
    const opponent = candidate.opponents[0]?.name || candidate.opponents[0]?.subject || "一名对手";
    if (candidate.familyId === "public-handshake") return {
      title: `${actor}与${opponent}在赛后主动握手`,
      detail: `终场哨响后，${actor}走向${opponent}。两人只交换了几句近况，随后各自回到本队；场上的对抗也留在了比赛里。`
    };
    if (candidate.familyId === "rivalry-banter") return {
      title: `${actor}与${opponent}把旧梗带到这次交手`,
      detail: `赛前中圈，${actor}与${opponent}先交换了几句只有双方明白的短句；开球后第一次对位立刻把玩笑切回竞争。`
    };
    return null;
  }

  function chooseOutcome(registry, rng) {
    const branch = weightedPick(registry.outcomeBranches || [], item => item.weight, rng);
    if (!branch) return null;
    const naturalCopy = (branch.copy || []).filter(copy => !/数据栏|故事停留|既定实力|真实的注脚/.test(copy));
    return { id: branch.id, tone: branch.tone, copy: pick(naturalCopy, rng) };
  }

  function chooseCrossTeamOutcome(rng) {
    return weightedPick([
      { id: "mutual-respect", tone: "positive", weight: .28, copy: "这次交流让双方多了一点尊重，但下一次对位仍不会留手。" },
      { id: "competitive-edge", tone: "negative", weight: .24, copy: "短暂交流没有消除竞争，下一次碰面反而更有针锋相对的味道。" },
      { id: "public-cooldown", tone: "repair", weight: .28, copy: "镜头前的互动让旧摩擦稍微降温，双方随后各自回到本队准备下一场。" },
      { id: "game-only", tone: "neutral", weight: .2, copy: "终场后话题很快回到比赛本身，双方没有继续展开。" }
    ], item => item.weight, rng);
  }

