    if (!text || /\bundefined\b|\{\{[^}]+\}\}|\{\d+\}/i.test(text)) {
      text = isEnglish(locale)
        ? `A shared connection between ${names.join(" and ")} resurfaced around Game ${gameNumber}, without changing either rotation.`
        : `G${gameNumber} 前，${names.join("和")}的一段旧关系再次被提起；比赛和轮换照常进行。`;
    }
